const languages=[...languageSelect.matchAll(/<option value="([a-z]+)"/g)].map(m=>m[1]);assert.equal(languages.length,12);assert.deepEqual([...languages].sort(),Object.keys(memo).sort());assert.deepEqual([...languages].sort(),Object.keys(link).sort());
const prefix='/citronex-dragon-guide/',mime={html:'text/html',js:'application/javascript',css:'text/css',svg:'image/svg+xml',png:'image/png',webmanifest:'application/manifest+json'};
const server=createServer((req,res)=>{const u=new URL(req.url,'http://localhost'),path=u.pathname.startsWith(prefix)?u.pathname.slice(prefix.length)||'index.html':'';report.requests.push({path,search:u.search,method:req.method});if(!['GET','HEAD'].includes(req.method)||!current.has(path)){res.writeHead(404).end();return;}const b=current.get(path);res.writeHead(200,{'Content-Type':mime[path.split('.').at(-1)]||'application/octet-stream','Content-Length':b.length,'Cache-Control':'no-store'});res.end(req.method==='HEAD'?undefined:b);});
